brute:
function xorBeauty(nums) {
  // Evaluate the definition directly: every ordered triple, XORed together.
  const n = nums.length;
  let total = 0;
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      for (let k = 0; k < n; k++) total ^= (nums[i] | nums[j]) & nums[k];
  return total;
}

