function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  // Small values repeat often, so pairs that cancel show up; large ones use the full range.
  const top = size === 'large' || rand() < 0.4 ? 1000000000 : 1 + Math.floor(rand() * 15);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
